const listEstoqueProdutos = `-- name: ListEstoqueProdutos :many
SELECT p.id, p.nome, p.tipo, p.unidade_medida, p.fracionavel, p.ativo, u.nome AS unidade,
       COALESCE((SELECT sum(l.saldo) FROM estoque_lotes l WHERE l.produto_id = p.id AND l.deleted_at IS NULL), 0)::numeric AS saldo
FROM estoque_produtos p JOIN estoque_unidades u ON u.id = p.unidade_id
WHERE p.deleted_at IS NULL
  AND ($1::text = '' OR position(lower($1::text) in lower(p.nome)) > 0)
  AND ($2::text = '' OR p.tipo = $2::text)
  AND ($3::bigint IS NULL OR p.unidade_id = $3::bigint)
  AND ($4::text = '' OR ($4::text = 'ativo') = p.ativo)
ORDER BY
  CASE WHEN $5::text = 'nome' AND $6::text = 'desc' THEN lower(p.nome) END DESC,
  CASE WHEN $5::text = 'id' AND $6::text = 'asc' THEN p.id END ASC,
  CASE WHEN $5::text = 'id' AND $6::text = 'desc' THEN p.id END DESC,
  lower(p.nome), p.id
LIMIT $8::int OFFSET $7::int
`

type ListEstoqueProdutosParams struct {
	Busca        string      `json:"busca"`
	Tipo         string      `json:"tipo"`
	UnidadeID    pgtype.Int8 `json:"unidade_id"`
	Situacao     string      `json:"situacao"`
	Ordem        string      `json:"ordem"`
	Dir          string      `json:"dir"`
	Deslocamento int32       `json:"deslocamento"`
	Limite       int32       `json:"limite"`
}

